import org.apache.commons.cli.ParseException;
import org.apache.commons.cli.TypeHandler;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;

import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.nio.file.Files;
import java.nio.file.Path;

import static org.junit.jupiter.api.Assertions.*;

public class TypeHandler_OpenFileTest {

    private Path tempFile;

    @AfterEach
    void cleanup() throws IOException {
        if (tempFile != null && Files.exists(tempFile)) {
            Files.delete(tempFile);
            tempFile = null;
        }
    }

    @Test
    @SuppressWarnings("deprecation")
    void testOpenFile_withExistingFile_returnsFileInputStream() throws Exception {
        // create temporary file with known content
        tempFile = Files.createTempFile("typehandler-test", ".txt");
        byte[] content = new byte[]{1, 2, 3, 4, 5};
        Files.write(tempFile, content);

        // call the deprecated public API
        try (FileInputStream fis = TypeHandler.openFile(tempFile.toString())) {
            assertNotNull(fis, "Expected a non-null FileInputStream for existing file");
            int first = fis.read();
            assertEquals(1, first, "First byte should match written content");
        }
    }

    @Test
    @SuppressWarnings("deprecation")
    void testOpenFile_withNonExistentFile_throwsParseException() {
        String nonExistent = new File("this-file-should-not-exist-" + System.nanoTime() + ".tmp").getAbsolutePath();
        assertThrows(ParseException.class, () -> TypeHandler.openFile(nonExistent));
    }

    @Test
    void testPrivateCreateValue_reflection_success() throws Exception {
        // create temp file
        tempFile = Files.createTempFile("typehandler-reflect-success", ".bin");
        byte[] content = new byte[]{42};
        Files.write(tempFile, content);

        // find private static createValue method via reflection and invoke it
        Method createValue = findCreateValueMethod();
        assertNotNull(createValue, "Expected a createValue(String, Class) private method");

        createValue.setAccessible(true);
        Object result = createValue.invoke(null, tempFile.toString(), FileInputStream.class);
        assertNotNull(result, "Reflection result should not be null");
        assertTrue(result instanceof FileInputStream, "Expected result to be a FileInputStream");

        // ensure it can be read
        FileInputStream fis = (FileInputStream) result;
        try (FileInputStream closeable = fis) {
            int r = closeable.read();
            assertEquals(42, r);
        }
    }

    @Test
    void testPrivateCreateValue_reflection_nonExistent_throwsParseExceptionCause() throws Exception {
        String nonExistent = new File("nonexistent-reflect-" + System.nanoTime() + ".tmp").getAbsolutePath();

        Method createValue = findCreateValueMethod();
        assertNotNull(createValue, "Expected a createValue(String, Class) private method");
        createValue.setAccessible(true);

        try {
            createValue.invoke(null, nonExistent, FileInputStream.class);
            fail("Expected invocation to throw an exception wrapping ParseException");
        } catch (InvocationTargetException ite) {
            Throwable cause = ite.getCause();
            assertNotNull(cause, "InvocationTargetException should have a cause");
            assertTrue(cause instanceof ParseException, "Cause should be ParseException for non-existent file");
        }
    }

    // Helper to locate a private static createValue method with parameters (String, Class)
    private Method findCreateValueMethod() {
        for (Method m : TypeHandler.class.getDeclaredMethods()) {
            if ("createValue".equals(m.getName())) {
                Class<?>[] params = m.getParameterTypes();
                if (params.length == 2 && params[0] == String.class && params[1] == Class.class) {
                    return m;
                }
            }
        }
        return null;
    }
}

